using System;using System.Drawing;using System.Reflection;using System.Runtime.InteropServices;using CelesteMusicPlayer;
class Program{[DllImport("user32.dll")]static extern bool DestroyIcon(nint icon);static void Main(){var h=(nint)typeof(WindowsTrayIcon).GetMethod("LoadTrayIcon",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,null)!;if(h==0)throw new Exception("missing production tray icon");try{using var image=Icon.FromHandle(h).ToBitmap();var c=image.GetPixel(image.Width/2,image.Height/2);if(c.R!=38||c.G!=59||c.B!=96)throw new Exception("production tray fell back to default icon: "+c);Console.WriteLine("PASS actual WindowsTrayIcon.LoadTrayIcon: deep-blue play RGB 38/59/96");}finally{DestroyIcon(h);}}}
